// Why Code: textul alertei + un item per chat de broker (TG_BROKER_CHAT_IDS, separate prin virgulă).
// Datele vin de la Error Trigger: execution (id, url, error, lastNodeExecuted, mode) sau trigger.error dacă a căzut triggerul.
const d = $input.first().json ?? {};
const wf = d.workflow ?? {};
const ex = d.execution ?? {};
const err = ex.error ?? d.trigger?.error ?? {};
const clip = (s, n) => { const t = String(s ?? '').replace(/\s+/g, ' ').trim(); return t.length > n ? t.slice(0, n - 1) + '…' : t; };

const lines = [
  '⚠️ Eroare în n8n',
  `Workflow: ${clip(wf.name || wf.id || 'necunoscut', 80)}`,
  `Nod: ${clip(ex.lastNodeExecuted || err.node?.name || 'necunoscut', 80)}`,
  `Eroare: ${clip(err.message || err.description || 'fără mesaj', 300)}`,
  ex.mode ? `Mod: ${ex.mode}${ex.retryOf ? ` (reîncercare a ${ex.retryOf})` : ''}` : null,
  ex.url ? `Execuția: ${ex.url}` : (ex.id ? `Execuția #${ex.id}` : 'Execuția nu a pornit (a căzut triggerul).'),
].filter(Boolean);

const chats = String($env.TG_BROKER_CHAT_IDS ?? '').split(',').map((x) => x.trim()).filter(Boolean);
if (!chats.length) throw new Error('TG_BROKER_CHAT_IDS lipsește din mediul n8n: alerta nu are destinatar.');
return chats.map((chatId) => ({ json: { chatId, text: lines.join('\n') } }));
